func testRolloutJetStream(t *testing.T) jetstream.JetStream {
	t.Helper()
	auth := newAuthenticatedNATS(t, "gru")
	runtime, err := auth.start(t, t.Context(), natscell.Config{Cell: "gru", Embedded: &natscell.Embedded{}})
	if err != nil {
		t.Fatal(err)
	}
	return runtime.JetStream()
}

func newAuthenticatedNATS(t *testing.T, cell string, brokers ...string) *authenticatedNATS {
	t.Helper()
	a := &authenticatedNATS{root: t.TempDir(), cell: cell, brokers: slices.Clone(brokers)}
	a.tls, a.routePassword = testR3TLSMaterial(t, a.root)
	operator, err := nkeys.CreateOperator()
	if err != nil {
		t.Fatal(err)
	}
	system, err := nkeys.CreateAccount()
	if err != nil {
		t.Fatal(err)
	}
	a.account, err = nkeys.CreateAccount()
	if err != nil {
		t.Fatal(err)
	}
	operatorID, _ := operator.PublicKey()
	systemID, _ := system.PublicKey()
	a.cellID, _ = a.account.PublicKey()
	operatorClaim := jwt.NewOperatorClaims(operatorID)
	operatorClaim.SystemAccount = systemID
	operatorJWT, err := operatorClaim.Encode(operator)
	if err != nil {
		t.Fatal(err)
	}
	systemJWT, err := jwt.NewAccountClaims(systemID).Encode(operator)
	if err != nil {
		t.Fatal(err)
	}
	cellClaim := jwt.NewAccountClaims(a.cellID)
	cellClaim.Limits.JetStreamLimits = jwt.JetStreamLimits{MemoryStorage: 256 << 20, DiskStorage: 8 << 30, Streams: 100, Consumer: 100}
	a.cellJWT, err = cellClaim.Encode(operator)
	if err != nil {
		t.Fatal(err)
	}
	write := func(name, raw string) string {
		path := filepath.Join(a.root, name)
		if err := os.WriteFile(path, []byte(raw), 0o600); err != nil {
			t.Fatal(err)
		}
		return path
	}
	a.operatorFile = write("operator.jwt", operatorJWT)
	a.systemFile = write("system.jwt", systemJWT)
	a.cellFile = write("cell.jwt", a.cellJWT)
	systemUser, systemCredentials := testBrokerJWTUser(t, a.root, "system.creds", system, systemID,
		[]string{"$SYS.REQ.ACCOUNT." + a.cellID + ".CLAIMS.UPDATE"}, nil)
	systemClaim, err := jwt.DecodeUserClaims(testDecoratedJWT(t, systemCredentials))
	if err != nil {
		t.Fatal(err)
	}
	systemClaim.Sub.Allow = jwt.StringList{protocol.InboxPrefix(cell, systemUser) + ".>"}
	a.systemCredentials = testBrokerJWTUserWithClaim(t, a.root, "system.creds", system, systemClaim)
	public, _ := testEd25519(t, a.root, "ticket.key")
	a.ticketPrivateFile = filepath.Join(a.root, "ticket.key")
	a.ticketPublicFile = write("ticket.pub", base64.StdEncoding.EncodeToString(public))
	return a

func (a *authenticatedNATS) config(t *testing.T, cfg natscell.Config) natscell.Config {
	t.Helper()
	if cfg.Cell != "" && cfg.Cell != a.cell {
		t.Fatalf("fixture cell %q differs from client cell %q", a.cell, cfg.Cell)
	}
	cfg.Cell = a.cell
	if cfg.Instance == "" {
		cfg.Instance = "one"
	}
	if cfg.Replicas == 0 {
		cfg.Replicas = 1
	}
	role := cfg.ClientRole
	if role == "" {
		role = "controller"
	}
	var user nkeys.KeyPair
	var err error
	if cfg.NKeySeedFile != "" {
		seed, readErr := os.ReadFile(cfg.NKeySeedFile)
		if readErr != nil {
			t.Fatal(readErr)
		}
		user, err = nkeys.FromSeed(seed)
		clear(seed)
	} else if cfg.CredentialsFile != "" {
		credentials, readErr := os.ReadFile(cfg.CredentialsFile)
		if readErr != nil {
			t.Fatal(readErr)
		}
		user, err = nkeys.ParseDecoratedUserNKey(credentials)
		clear(credentials)
	} else {
		user, err = nkeys.CreateUser()
	}
	if err != nil {
		t.Fatal(err)
	}
	defer user.Wipe()
	public, err := user.PublicKey()
	if err != nil {
		t.Fatal(err)
	}
	claim := jwt.NewUserClaims(public)
	claim.IssuerAccount = a.cellID
	claim.Sub.Allow = jwt.StringList{protocol.InboxPrefix(a.cell, public) + ".>"}
	switch role {
	case "controller":
		claim.Pub.Allow = natscell.ControllerPublishes(a.cell)
		claim.Pub.Allow.Add(natscell.GlobalControllerPublishes()...)
		claim.Pub.Allow.Add(natscell.GlobalControllerRequests()...)
		claim.Pub.Allow.Add("$JS.ACK.>")
		claim.Sub.Allow.Add(natscell.ControllerSubscriptions(a.cell)...)
		claim.Sub.Allow.Add(natscell.GlobalControllerRequests()...)
		claim.Sub.Allow.Add(protocol.ObservabilityGrant(a.cell), protocol.Broker(a.cell, "ticket", ">"), protocol.Broker(a.cell, "fence", cfg.Instance))
		claim.Resp = &jwt.ResponsePermission{MaxMsgs: 1, Expires: 5 * time.Second}
	case "operator":
		claim.Pub.Allow = natscell.BrokerOperatorPublishPermissions(a.cell)
	case "host":
		claim.Pub.Allow = jwt.StringList{protocol.AgentObservation(a.cell, public, "*")}
	default:
		t.Fatalf("unsupported authenticated fixture role %q", role)
	}
	cfg.CredentialsFile = testBrokerJWTUserWithKey(t, a.root, cfg.Instance+"-"+public+".creds", a.account, user, claim)
	cfg.NKeySeedFile = ""
	cfg.TLS = a.tls
	cfg.URL = strings.ReplaceAll(cfg.URL, "nats://", "tls://")
	if cfg.Embedded != nil {
		embedded := *cfg.Embedded
		cfg.Embedded = &embedded
		embedded.Users = nil
		embedded.TLS, embedded.RouteTLS = a.tls, a.tls
		embedded.RouteUser, embedded.RoutePasswordFile = "integration-route", a.routePassword
		embedded.OperatorJWTFile, embedded.SystemJWTFile, embedded.CellJWTFile = a.operatorFile, a.systemFile, a.cellFile
		embedded.SystemCredentialsFile, embedded.TicketPublicKeyFile = a.systemCredentials, a.ticketPublicFile
		embedded.BrokerIDs = slices.Clone(a.brokers)
		if len(embedded.BrokerIDs) == 0 {
			embedded.BrokerIDs = []string{cfg.Instance}
		}
		if embedded.StoreDir == "" {
			embedded.StoreDir = filepath.Join(a.root, cfg.Instance)
		}
		if embedded.Host == "" {
			embedded.Host = "127.0.0.1"
		}
		if embedded.Port == 0 {
			embedded.Port = reserveControllerPort(t)
		}
	}
	return cfg
}

func (a *authenticatedNATS) start(t *testing.T, ctx context.Context, cfg natscell.Config) (*natscell.Runtime, error) {
	t.Helper()
	runtime, err := natscell.Start(ctx, a.config(t, cfg))
	if err != nil {
		return nil, err
	}
	t.Cleanup(func() { _ = runtime.Close() })
	if cfg.Embedded != nil {
		if err := runtime.ApplyCellClaim(ctx, 1, a.cellJWT); err != nil {
			return nil, fmt.Errorf("apply fixture claim: %w", err)
		}
		if err := runtime.Bridge().OpenUntil(1, a.cellJWT, time.Now().Add(5*time.Minute)); err != nil {
			return nil, fmt.Errorf("open fixture bridge: %w", err)
		}
	}
	return runtime, nil
}

func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

// StartIdentityRekey joins only the existing regional quorum. The caller must
// verify its root checkpoint before opening it and close it after shared reset
// completion before starting normal external transports on the same store.
func StartIdentityRekey(ctx context.Context, cfg Config) (*Runtime, error) {
	if cfg.Embedded == nil {
		return nil, errors.New("identity rekey requires an installed production broker")
	}
	return start(ctx, cfg, true)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}

		connectURL = bridgeClientURLs(connectURL)
	}
	r.conn, connectErr = nats.Connect(connectURL, options...)
	close(connected)
}()
select {
case <-connectCtx.Done():
	// nats.Connect has a bounded timeout of its own; wait for the goroutine
	// before cleaning up to avoid a late client after server shutdown.
	<-connected
	if forwardErr != nil {
		return nil, forwardErr
	}
	return nil, unavailable{connectCtx.Err()}
case <-connected:
}
if forwardErr != nil {
	return nil, forwardErr
}
if connectErr != nil {
	err := fmt.Errorf("connect regional NATS: %w", connectErr)
	if errors.Is(connectErr, nats.ErrAuthorization) {
		// The brokers answered and refused these credentials.
		return nil, err
	}

func (s *channelSource) get(ctx context.Context) (releasechannel.Location, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.location != nil {
		return *s.location, nil
	}
	location, err := s.open(ctx)
	if err != nil {
		return releasechannel.Location{}, err
	}
	s.location = &location
	return location, nil
}

func openChannelBucket(ctx context.Context, js jetstream.JetStream, replicas int) (jetstream.KeyValue, error) {
	for {
		ctx := observability.StartTrace(ctx)
		kv, err := js.KeyValue(ctx, releasechannel.Bucket)
		if errors.Is(err, jetstream.ErrBucketNotFound) {
			kv, err = js.CreateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: releasechannel.Bucket,
				Storage: jetstream.FileStorage, Replicas: replicas, History: 4, MaxValueSize: releasechannel.MaxValueBytes})
		}
		if err == nil {
			return kv, nil
		}
		slog.WarnContext(ctx, "open the release channel bucket", observability.ComponentKey, "rollout", "error", err)
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(5 * time.Second):
		}
	}
}

func (s *channelSource) readNativeClaim(ctx context.Context, role string) ([]byte, bool, error) {
	if s.client != nil {
		observation, err := s.client.NativeRelease(ctx, rootoci.NativeReleaseRequest{Role: role})
		if err != nil {
			return nil, false, err
		}
		if !time.Now().Before(observation.ExpiresAt) || observation.Found && (len(observation.Claim) > releasechannel.MaxServiceClaimBytes || controllerSHA256(observation.Claim) != observation.ClaimSHA256) {
			return nil, false, rootoci.ErrUnauthorized
		}
		return observation.Claim, observation.Found, nil
	}
	location, err := s.get(ctx)
	if err != nil {
		return nil, false, err
	}
	return releasechannel.ReadServiceClaim(ctx, location, role)
}

type channelBucket struct {
	mu      sync.Mutex
	objects map[string][]byte
	etags   map[string]string
	version int
	puts    map[string]int
}

func newChannelBucket() *channelBucket {
	return &channelBucket{objects: map[string][]byte{}, etags: map[string]string{}, puts: map[string]int{}}
}

type objectStatus int

func (err objectStatus) Error() string          { return fmt.Sprintf("HTTP %d", int(err)) }
func (err objectStatus) GetHTTPStatusCode() int { return int(err) }
func (objectStatus) GetMessage() string         { return "" }
func (objectStatus) GetCode() string            { return "" }
func (objectStatus) GetOpcRequestID() string    { return "" }

func (b *channelBucket) GetObject(_ context.Context, request objectstorage.GetObjectRequest) (objectstorage.GetObjectResponse, error) {
	b.mu.Lock()
	defer b.mu.Unlock()
	data, ok := b.objects[*request.ObjectName]
	if !ok {
		return objectstorage.GetObjectResponse{}, objectStatus(404)
	}
	etag := b.etags[*request.ObjectName]
	return objectstorage.GetObjectResponse{Content: io.NopCloser(bytes.NewReader(data)), ETag: &etag}, nil
}

func (b *channelBucket) PutObject(_ context.Context, request objectstorage.PutObjectRequest) (objectstorage.PutObjectResponse, error) {
	data, err := io.ReadAll(request.PutObjectBody)
	if err != nil {
		return objectstorage.PutObjectResponse{}, err
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	name := *request.ObjectName
	etag, exists := b.etags[name]
	if request.IfNoneMatch != nil && exists || request.IfMatch != nil && *request.IfMatch != etag {
		return objectstorage.PutObjectResponse{}, objectStatus(412)
	}
	b.version++
	b.objects[name], b.etags[name] = data, fmt.Sprintf("etag-%d", b.version)
	b.puts[name]++
	return objectstorage.PutObjectResponse{}, nil
}

func (location Location) write(ctx context.Context, name string, wire []byte) error {
	if len(wire) > maxStatusBytes {
		return fmt.Errorf("%w: %s exceeds %d bytes", ErrInvalid, name, maxStatusBytes)
	}
	_, err := location.Client.PutObject(ctx, objectstorage.PutObjectRequest{
		NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name,
		ContentLength: new(int64(len(wire))), PutObjectBody: io.NopCloser(bytes.NewReader(wire)),
		ContentType: new("application/json"),
	})
	if err != nil {
		return fmt.Errorf("write %s/%s: %w", location.Bucket, name, err)
	}
	return nil
}

func (location Location) read(ctx context.Context, name string, limit int64, value any) (bool, error) {
	data, _, found, err := location.get(ctx, name, limit)
	if err != nil || !found {
		return found, err
	}
	if err := json.Unmarshal(data, value); err != nil {
		return true, fmt.Errorf("%w: decode %s: %w", ErrInvalid, name, err)
	}
	return true, nil
}

func (location Location) get(ctx context.Context, name string, limit int64) ([]byte, string, bool, error) {
	response, err := ociclient.ReadObject(ctx, location.Client, objectstorage.GetObjectRequest{
		NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name,
	})
	if httpStatus(err) == http.StatusNotFound {
		return nil, "", false, nil
	}
	if err != nil {
		return nil, "", false, fmt.Errorf("read %s/%s: %w", location.Bucket, name, err)
	}
	defer response.Content.Close()
	data, err := io.ReadAll(io.LimitReader(response.Content, limit+1))
	if err != nil {
		return nil, "", false, fmt.Errorf("read %s/%s: %w", location.Bucket, name, err)
	}
	if int64(len(data)) > limit {
		return nil, "", false, fmt.Errorf("%w: %s/%s exceeds %d bytes", ErrInvalid, location.Bucket, name, limit)
	}
	if response.ETag == nil || *response.ETag == "" {
		return nil, "", false, fmt.Errorf("read %s/%s: no ETag", location.Bucket, name)
	}
	return data, *response.ETag, true, nil
}

func ReadServiceStatus(ctx context.Context, location Location, role string) (ServiceStatus, bool, error) {
	var status ServiceStatus
	found, err := location.read(ctx, ServiceStatusObject(role), maxStatusBytes, &status)
	return status, found, err
}

// WriteServiceStatus replaces role's status; only the region's authority
// leader writes it.
func WriteServiceStatus(ctx context.Context, location Location, status ServiceStatus) error {
	status.Schema, status.Reason = ServiceStatusSchema, Clip(status.Reason)
	wire, err := json.Marshal(status, json.Deterministic(true))
	if err != nil {
		return err
	}
	return location.write(ctx, ServiceStatusObject(status.Role), wire)
}

// ReadServiceBinary copies role's binary with digest to dst, at most
// MaxServiceBinaryBytes. The caller checks the bytes against the claim.
func ReadServiceBinary(ctx context.Context, location Location, role, digest string, dst io.Writer) error {
	name := ServiceBinaryObject(role, digest)
	response, err := ociclient.ReadObject(ctx, location.Client, objectstorage.GetObjectRequest{
		NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name,
	})
	if err != nil {
		return fmt.Errorf("read %s/%s: %w", location.Bucket, name, err)
	}
	defer response.Content.Close()
	read, err := io.Copy(dst, io.LimitReader(response.Content, MaxServiceBinaryBytes+1))
	if err != nil {
		return fmt.Errorf("read %s/%s: %w", location.Bucket, name, err)
	}
	if read > MaxServiceBinaryBytes {
		return fmt.Errorf("%w: %s/%s exceeds %d bytes", ErrInvalid, location.Bucket, name, MaxServiceBinaryBytes)
	}
	return nil
}

