func servicePinsFixture(t *testing.T) (*serviceReleases, jetstream.KeyValue, *channelBucket, releasechannel.Location) {
	t.Helper()
	js := testRolloutJetStream(t)
	kv, err := openChannelBucket(t.Context(), js, 1)
	if err != nil {
		t.Fatal(err)
	}
