func Open(ctx context.Context, cfg Config) (*Service, error) {
	if cfg.Conn == nil || cfg.JS == nil || !validCell(cfg.Cell) || cfg.Replicas != 1 && cfg.Replicas != 3 && cfg.Replicas != 5 || cfg.ArtifactStoreMaxBytes < 0 {
		return nil, fmt.Errorf("%w: delivery service configuration", ErrInvalid)
	}
	artifactStoreMaxBytes := cfg.ArtifactStoreMaxBytes
	if artifactStoreMaxBytes == 0 {
		artifactStoreMaxBytes = DefaultArtifactStoreMaxBytes
	}
	// A larger quota already in force came from the cell spec
	// (artifact_store), which the leader re-applies; a restart must not
	// shrink the store under an upload before then.
	if existing, err := cfg.JS.Stream(ctx, "OBJ_"+ArtifactBucket); err == nil {
		artifactStoreMaxBytes = max(artifactStoreMaxBytes, existing.CachedInfo().Config.MaxBytes)
	} else if !errors.Is(err, jetstream.ErrStreamNotFound) {
		return nil, fmt.Errorf("inspect artifact store limits: %w", err)
	}
	s := &Service{js: cfg.JS, config: cfg}
	var err error
	s.artifacts, err = cfg.JS.CreateOrUpdateObjectStore(ctx, artifactStoreConfig(cfg.Replicas, artifactStoreMaxBytes))
	if err != nil {
		return nil, fmt.Errorf("artifact store: %w", err)
	}
	stream, err := cfg.JS.Stream(ctx, "OBJ_"+ArtifactBucket)
	if err != nil {
		if errors.Is(err, jetstream.ErrStreamNotFound) {
			return nil, fmt.Errorf("%w: inspect artifact store limits: %w", ErrStoreNotReady, err)
		}
		return nil, fmt.Errorf("inspect artifact store limits: %w", err)
	}
	streamInfo, err := stream.Info(ctx)
	if err != nil {
		if errors.Is(err, jetstream.ErrStreamNotFound) {
			return nil, fmt.Errorf("%w: inspect artifact store limits: %w", ErrStoreNotReady, err)
		}
		return nil, fmt.Errorf("inspect artifact store limits: %w", err)
	}
	if streamInfo.Config.MaxBytes != artifactStoreMaxBytes || streamInfo.Config.Discard != jetstream.DiscardNew {
		return nil, fmt.Errorf("%w: artifact store must enforce the configured byte quota with discard-new", ErrInvalid)
	}
	s.admissions, err = cfg.JS.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: AdmissionBucket, Storage: jetstream.FileStorage, Replicas: cfg.Replicas, History: 1})
	if err != nil {
		return nil, fmt.Errorf("artifact admissions: %w", err)
	}
	s.operations, err = cfg.JS.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: OperationBucket, Storage: jetstream.FileStorage, Replicas: cfg.Replicas, History: 4})
	if err != nil {
		return nil, fmt.Errorf("delivery operations: %w", err)
	}
	_, err = cfg.JS.CreateOrUpdateStream(ctx, jetstream.StreamConfig{Name: IntentStream, Subjects: []string{IntentSubject(cfg.Cell)}, Storage: jetstream.FileStorage, Replicas: cfg.Replicas, Retention: jetstream.WorkQueuePolicy, Discard: jetstream.DiscardNew, MaxMsgs: 100_000, MaxBytes: 1 << 30, MaxMsgSize: MaxIntentBytes + 8192, Duplicates: 2 * time.Minute})
	if err != nil {
		return nil, fmt.Errorf("delivery intent stream: %w", err)
	}
	s.consumer, err = cfg.JS.CreateOrUpdateConsumer(ctx, IntentStream, intentConsumerConfig(cfg.Cell))
	if err != nil {
		return nil, fmt.Errorf("delivery intent consumer: %w", err)
	}
	return s, nil
}

func (s *Service) storeArtifact(ctx context.Context, snapshot *os.File, r ArtifactRecord) error {
	exists, err := s.artifactExistsForUpload(ctx, r)
	if err != nil {
		return err
	}
	if exists {
		return nil
	}
	if _, err := snapshot.Seek(0, io.SeekStart); err != nil {
		return err
	}
	// Without a deadline every chunk ack gets only the JetStream default
	// timeout, which a slow operator link such as a bastion forward misses.
	uploadCtx, cancel := context.WithTimeout(ctx, artifactUploadTimeout)
	defer cancel()
	if _, err := s.artifacts.Put(uploadCtx, jetstream.ObjectMeta{Name: artifactKey(r.Digest)}, contextReader{uploadCtx, snapshot}); err != nil {
		if isArtifactStoreFullError(err) {
			return fmt.Errorf("store artifact: %w: %w", ErrArtifactStoreFull, err)
		}
		return fmt.Errorf("store artifact: %w", err)
	}
	return s.verifyArtifact(ctx, r)
}

// AdmitClaim is the controller's in-process admission of an artifact that
// CI uploaded somewhere only the controller reads (the region's head
// bucket, TS-610) with its signed claim. The claim is verified at its
// issuance instant, as an archived admission is, so the caller bounds its
// age; the bytes must be exactly the claimed ones. It returns the record and
// the authorized actor.
func (s *Service) AdmitClaim(ctx context.Context, reader io.ReadSeeker, claim []byte) (_ ArtifactRecord, _ string, resultErr error) {
	r, actor, err := s.VerifyClaim(ctx, claim)
	if err != nil {
		return ArtifactRecord{}, "", err
	}
	snapshot, size, digest, err := stageArtifact(ctx, reader)
	if err != nil {
		return ArtifactRecord{}, "", err
	}
	defer func() { resultErr = errors.Join(resultErr, discardStagedArtifact(snapshot)) }()
	if size != r.Size || digest != r.Digest {
		return ArtifactRecord{}, "", fmt.Errorf("%w: the artifact bytes are not the claimed ones", ErrInvalid)
	}
	if err := s.storeArtifact(ctx, snapshot, r); err != nil {
		return ArtifactRecord{}, "", err
	}
	if err := s.touchArtifact(ctx, r.Digest); err != nil {
		return ArtifactRecord{}, "", err
	}
	if err := s.persistArtifactAdmission(ctx, r, claim, actor); err != nil {
		return ArtifactRecord{}, "", err
	}
	return r, actor, nil
}

// VerifyClaim checks a signed artifact claim at its issuance instant and
// authorizes its signer for the claimed role, environment and repository,
// without admitting anything. It returns the record and the actor.
func (s *Service) VerifyClaim(ctx context.Context, claim []byte) (ArtifactRecord, string, error) {
	if s == nil || s.config.ArtifactVerifier == nil || s.config.AuthorizeArtifact == nil || len(claim) == 0 || len(claim) > MaxArtifactClaimBytes {
		return ArtifactRecord{}, "", fmt.Errorf("%w: artifact admission configuration or signed claim", ErrInvalid)
	}
	r, actor, err := s.config.ArtifactVerifier.VerifyArchivedArtifact(ctx, claim)
	if err != nil || actor == "" || r.validate() != nil || r.Cell != s.config.Cell {
		return ArtifactRecord{}, "", fmt.Errorf("%w: artifact signature or cell", ErrInvalid)
	}
	if err := s.config.AuthorizeArtifact(ctx, actor, r); err != nil {
		return ArtifactRecord{}, "", err
	}
	return r, actor, nil

func (s *Service) persistArtifactAdmission(ctx context.Context, record ArtifactRecord, envelope []byte, actor string) error {
	key := admissionKey(record.Digest, record.Cell, record.Role, record.Environment)
	newAdmission := signedAdmission{Record: record, Envelope: bytes.Clone(envelope), Actor: actor}
	encoded, err := json.Marshal(newAdmission)
	if err != nil {
		return err
	}
	for range admissionCASAttempts {
		entry, getErr := s.getAdmission(ctx, key)
		if errors.Is(getErr, jetstream.ErrKeyNotFound) {
			if _, createErr := s.admissions.Create(ctx, key, encoded); createErr == nil {
				return s.verifyCurrentAdmission(ctx, record)
			} else if errors.Is(createErr, jetstream.ErrKeyExists) {
				continue
			} else {
				return fmt.Errorf("admit artifact: %w", createErr)
			}
		}
		if getErr != nil {
			return getErr
		}
		oldAdmission, err := decodeStoredAdmission(entry.Value(), record.Digest, record.Cell, record.Role, record.Environment)
		if err != nil {
			return err
		}
		if oldAdmission.Record != record {
			return ErrConflict
		}
		if oldAdmission.Actor == actor && bytes.Equal(oldAdmission.Envelope, envelope) {
			return s.verifyCurrentAdmission(ctx, record)
		}
		if current, currentErr := s.readAdmission(ctx, record.Digest, record.Cell, record.Role, record.Environment); currentErr == nil {
			if current != record {
				return ErrConflict
			}
			return nil
		}
		if err := ctx.Err(); err != nil {
			return err
		}
		if err := s.config.AuthorizeArtifact(ctx, actor, record); err != nil {
			return err
		}
		if err := s.verifyArtifact(ctx, record); err != nil {
			return err

func (s *Service) getAdmission(ctx context.Context, key string) (*operationValue, error) {
	if s == nil || s.config.Conn == nil {
		return nil, errors.New("delivery admission leader read requires NATS connection")
	}
	js, err := s.config.Conn.JetStream()
	if err != nil {
		return nil, err
	}
	subject := "$KV." + AdmissionBucket + "." + key
	msg, err := js.GetLastMsg("KV_"+AdmissionBucket, subject, nats.Context(ctx))
	if errors.Is(err, nats.ErrMsgNotFound) {
		return nil, jetstream.ErrKeyNotFound
	}
	if err != nil {
		return nil, err
	}
	return operationValueFromMsg(subject, msg)
}

func (s *Service) readAdmission(ctx context.Context, digest, cell, role, environment string) (ArtifactRecord, error) {
	e, err := s.getAdmission(ctx, admissionKey(digest, cell, role, environment))
	if err != nil {
		return ArtifactRecord{}, err
	}
	signed, err := decodeStoredAdmission(e.Value(), digest, cell, role, environment)
	if err != nil {
		return ArtifactRecord{}, err
	}
	r := signed.Record

func (s *Service) ResolveAdmittedArtifact(ctx context.Context, digest, role, environment string) (ArtifactRecord, error) {
	if s == nil || !sha256RE.MatchString(digest) || !nameRE.MatchString(role) || !nameRE.MatchString(environment) || !nameRE.MatchString(s.config.Cell) {
		return ArtifactRecord{}, fmt.Errorf("%w: artifact admission lookup", ErrInvalid)
	}
	record, err := s.readAdmission(ctx, digest, s.config.Cell, role, environment)
	if err != nil {
		return ArtifactRecord{}, err
	}
	if err := s.verifyArtifact(ctx, record); err != nil {
		return ArtifactRecord{}, err
	}
	return record, nil
}

func (s *Service) verifyArtifact(ctx context.Context, r ArtifactRecord) error {
	delay := 20 * time.Millisecond
	for attempt := range artifactVisibilityAttempts {
		exists, err := s.checkArtifact(ctx, r)
		if err == nil && exists {
			return nil
		}
		if !(err == nil && !exists || errors.Is(err, jetstream.ErrObjectNotFound)) {
			return err
		}
		if err := ctx.Err(); err != nil {
			return err
		}
		if attempt == artifactVisibilityAttempts-1 {
			return fmt.Errorf("%w: artifact object did not become visible", ErrInvalid)
		}
		timer := time.NewTimer(delay)
		select {
		case <-ctx.Done():
			timer.Stop()
			return ctx.Err()
		case <-timer.C:
		}
		delay = min(delay*2, maxArtifactVisibilityDelay)
	}
	return fmt.Errorf("%w: artifact object did not become visible", ErrInvalid)
}

const (
	artifactVisibilityAttempts = 8
	maxArtifactVisibilityDelay = 250 * time.Millisecond
)

func (s *Service) checkArtifact(ctx context.Context, r ArtifactRecord) (bool, error) {
	if r.Size <= 0 || r.Size > MaxArtifactBytes {
		return false, fmt.Errorf("%w: artifact size is outside bounds", ErrInvalid)
	}
	err := artifact.ReadVerified(ctx, s.js, s.artifacts, ArtifactBucket, artifactKey(r.Digest),
		r.Digest, r.Size, MaxArtifactBytes, io.Discard)
	if errors.Is(err, jetstream.ErrObjectNotFound) {
		return false, nil
	}
	if err != nil {
		if errors.Is(err, artifact.ErrInvalid) {
			return false, fmt.Errorf("%w: %w", ErrInvalid, err)
		}
		return false, err
	}
	return true, nil

func (s *Service) SubmitVerified(ctx context.Context, intent Intent, actor string) error {
	if s == nil || s.operations == nil || s.config.Authorize == nil || actor == "" {
		return errors.New("verified delivery submission is not configured")
	}
	if err := intent.Validate(); err != nil {
		return err
	}
	if intent.Cell != s.config.Cell {
		return fmt.Errorf("%w: wrong cell", ErrInvalid)
	}
	if err := s.config.Authorize(ctx, actor, intent.Clone()); err != nil {
		return err
	}
	wire, err := json.Marshal(intent)
	if err != nil {
		return err
	}
	if len(wire) > MaxIntentBytes {
		return fmt.Errorf("%w: intent too large", ErrInvalid)
	}
	fingerprint, err := intent.fingerprint()
	if err != nil {
		return err
	}
	verified, err := json.Marshal(struct {
		Intent Intent `json:"intent"`
		Actor  string `json:"actor"`
	}{intent, actor})
	if err != nil {
		return err
	}
	sum := sha256.Sum256(wire)
	if _, err := s.operations.Create(ctx, entityid.Derive("delivery-verified", hex.EncodeToString(sum[:])), verified); err != nil && !errors.Is(err, jetstream.ErrKeyExists) {
		return fmt.Errorf("record verified delivery intent: %w", err)
	}
	if err := s.publishIntent(ctx, IntentSubject(intent.Cell), wire, intent.OperationID+"."+fingerprint); err != nil {
		return fmt.Errorf("publish delivery intent: %w", err)
	}
	return nil
}

func (s *Service) publishIntent(ctx context.Context, subject string, wire []byte, msgID string) error {
	retryCtx, cancel := context.WithTimeout(ctx, intentPublishTimeout)
	defer cancel()

	backoff := intentPublishInitialBackoff
	var lastErr error
	for {
		if err := ctx.Err(); err != nil {
			return err
		}
		if err := retryCtx.Err(); err != nil {
			if lastErr != nil {
				return lastErr
			}
			return err
		}

		attemptCtx, cancelAttempt := context.WithTimeout(retryCtx, intentPublishAttemptTimeout)
		_, publishErr := s.js.Publish(attemptCtx, subject, wire, jetstream.WithMsgID(msgID), jetstream.WithRetryAttempts(0))
		attemptErr := attemptCtx.Err()
		cancelAttempt()
		if publishErr == nil {
			return nil
		}
		lastErr = publishErr
		if err := ctx.Err(); err != nil {
			return err
		}
		if retryCtx.Err() != nil {
			return publishErr
		}
		if !retryableIntentPublishError(publishErr, errors.Is(attemptErr, context.DeadlineExceeded)) {

func (s *Service) getOperation(ctx context.Context, key string) (*operationValue, error) {
	if s == nil || s.config.Conn == nil {
		return nil, errors.New("delivery operation leader read requires NATS connection")
	}
	js, err := s.config.Conn.JetStream()
	if err != nil {
		return nil, err
	}
	subject := "$KV." + OperationBucket + "." + key
	msg, err := js.GetLastMsg("KV_"+OperationBucket, subject, nats.Context(ctx))
	if errors.Is(err, nats.ErrMsgNotFound) {
		return nil, jetstream.ErrKeyNotFound
	}
	if err != nil {
		return nil, err
	}
	return operationValueFromMsg(subject, msg)
}

func operationValueFromMsg(subject string, msg *nats.RawStreamMsg) (*operationValue, error) {
	if msg == nil || msg.Subject != subject || msg.Sequence == 0 {
		return nil, errors.New("invalid delivery operation state")
	}
	if operation := msg.Header.Get("KV-Operation"); operation != "" {
		if operation == "DEL" || operation == "PURGE" {
			return nil, jetstream.ErrKeyNotFound
		}
		return nil, errors.New("invalid delivery operation marker")
	}
	if marker := msg.Header.Get(jetstream.MarkerReasonHeader); marker != "" {
		if marker == "MaxAge" || marker == "Purge" || marker == "Remove" {
			return nil, jetstream.ErrKeyNotFound
		}
		return nil, errors.New("invalid delivery operation marker")
	}
	if len(msg.Data) == 0 {
		return nil, errors.New("invalid delivery operation body")
	}
	return &operationValue{value: msg.Data, revision: msg.Sequence}, nil
}

func (s *Service) Status(ctx context.Context, operationID string) (Receipt, error) {
	return s.status(ctx, operationID, "")
}

func (s *Service) status(ctx context.Context, operationID, expectedFingerprint string) (Receipt, error) {
	if s == nil || !entityid.Valid(operationID) {
		return Receipt{}, ErrInvalid
	}
	e, err := s.getOperation(ctx, operationKey(operationID))
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Receipt{}, ErrPending
	}
	if err != nil {
		return Receipt{}, err
	}
	var op operation
	if err := json.Unmarshal(e.Value(), &op); err != nil {
		return Receipt{}, fmt.Errorf("decode delivery status: %w", err)
	}
	if op.Intent.OperationID != operationID {
		return Receipt{}, ErrConflict
	}
	fingerprint, err := op.Intent.Fingerprint()
	if err != nil || fingerprint != op.Fingerprint {
		return Receipt{}, fmt.Errorf("%w: invalid durable operation fingerprint", ErrInvalid)
	}
	if expectedFingerprint != "" && fingerprint != expectedFingerprint {
		return Receipt{}, ErrConflict
	}
	if op.Receipt == nil {
		return Receipt{}, ErrPending
	}
	if op.Receipt.OperationID != operationID || op.Receipt.Fingerprint != fingerprint || op.Receipt.ArtifactDigest != op.Intent.ArtifactDigest || op.Receipt.ManifestDigest != op.Intent.ManifestDigest {
		return Receipt{}, fmt.Errorf("%w: invalid durable delivery receipt", ErrInvalid)

func (s *Service) StatusFor(ctx context.Context, intent Intent) (Receipt, error) {
	fingerprint, err := intent.Fingerprint()
	if err != nil {
		return Receipt{}, err
	}
	return s.status(ctx, intent.OperationID, fingerprint)
}

func (s *Service) RefuseIntent(ctx context.Context, intent Intent, actor string, authorityEpoch uint64, reason string) error {
	if s == nil || s.operations == nil || s.config.Authorize == nil || s.config.Fencer == nil {
		return ErrInvalid
	}
	if actor == "" || reason == "" || len(reason) > 1024 || intent.Cell != s.config.Cell {
		return ErrInvalid
	}
	if err := intent.Validate(); err != nil {
		return err
	}
	if err := s.config.Authorize(ctx, actor, intent); err != nil {
		return err
	}
	if err := s.config.Fencer.Guard(ctx, authorityEpoch); err != nil {
		return err
	}
	wire, err := json.Marshal(intent)
	if err != nil {
		return err
	}
	terminal, err := s.recordIntentReceipt(ctx, wire, intent, actor, "rejected", reason)
	if err != nil {
		return err
	}
	if !terminal {
		return ErrConflict
	}
	entry, err := s.getOperation(ctx, operationKey(intent.OperationID))
	if err != nil {
		return err
	}
	var stored operation
	if err := json.Unmarshal(entry.Value(), &stored); err != nil {
		return err
	}
	fingerprint, err := intent.Fingerprint()
	if err != nil {
		return err
	}
	if stored.Fingerprint != fingerprint || stored.Actor != actor || stored.Receipt == nil || stored.Receipt.Status != "rejected" {
		return ErrConflict
	}
	return nil
}

func (s *Service) recordIntentReceipt(ctx context.Context, wire []byte, intent Intent, actor, status, reason string) (bool, error) {
	fingerprint, err := intent.fingerprint()
	if err != nil {
		return false, err
	}
	receipt := &Receipt{OperationID: intent.OperationID, Fingerprint: fingerprint, Status: status, Error: reason, ArtifactDigest: intent.ArtifactDigest, ManifestDigest: intent.ManifestDigest, Cell: intent.Cell, Role: intent.Role, Environment: intent.Environment, Generation: intent.Generation, AuthorityEpoch: intent.AuthorityEpoch}
	op := operation{Intent: intent, Fingerprint: fingerprint, Actor: actor, Receipt: receipt}
	b, err := json.Marshal(op)
	if err != nil {
		return false, err
	}
	key := operationKey(intent.OperationID)
	if _, err := s.operations.Create(ctx, key, b); err == nil {
		kind := decisionlog.KindDeliveryRejected
		if status == "held" {
			kind = decisionlog.KindDeliveryHeld
		}
		recordIntentDecision(ctx, intent, kind, decisionlog.StatusFailed, 0, reason)
		return true, nil
	} else if !errors.Is(err, jetstream.ErrKeyExists) {
		return false, fmt.Errorf("record %s intent: %w", status, err)
	}
	e, err := s.getOperation(ctx, key)
	if err != nil {
		return false, err
	}
	var existing operation
	if err := json.Unmarshal(e.Value(), &existing); err != nil {
		return false, err
	}
	if existing.Fingerprint == fingerprint && existing.Actor == actor && existing.Receipt != nil {
		return true, nil
	}
	return s.reject(ctx, wire, "operation ID already binds a different request")
}
